<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class LkdYoungApplication extends Model {protected $fillable=['user_id','university_id','department','education_level','club_name','club_role','motivation','contact_consent','wants_representative','status']; public function user(){return $this->belongsTo(User::class);} public function university(){return $this->belongsTo(Universities::class);}}
